Tool response:
Tool: search_products
Description: Search for products matching a query with specific filters.
Find the first product that matches the given search query, has 'Amazon's Choice' badge, and is fulfilled by Amazon (not a third-party seller).
Parameters:
    {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "Search query string",
          "title": "Query"
        },
        "is_amazons_choice": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter products that have 'Amazon's Choice' badge",
          "title": "Is Amazons Choice"
        },
        "is_fulfilled_by_amazon": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter products fulfilled by Amazon",
          "title": "Is Fulfilled By Amazon"
        }
      },
      "required": [
        "query"
      ]
    }
